function hitPlayer(amount){if(playerState.iframes>0)return;playerState.health=Math.max(0,playerState.health-amount);playerState.iframes=.65;player.scale.set(1.12,1.12,1.12);setTimeout(()=>player.scale.set(1,1,1),100);updateStats();if(playerState.health<=0){playerState.health=55;player.position.set(0,0,1);message('A floresta devolve seu último fôlego');toast('Você foi salvo pelo fragmento. Continue.');updateStats()}}
