function doAttack(power=false){if(!started||paused||gameWon)return;if(power){if(playerState.powerCd>0||playerState.energy<35)return;playerState.energy-=35;playerState.powerCd=4;attackFlash=.7;const pulse=new THREE.Mesh(new THREE.TorusGeometry(.8,.09,8,48),new THREE.MeshBasicMaterial({color:'#ccf29b',transparent:true,opacity:.85}));pulse.rotation.x=Math.PI/2;pulse.position.set(player.position.x,.7,player.position.z);scene.add(pulse);let s=1;const pulseTimer=setInterval(()=>{s+=.22;pulse.scale.set(s,s,s);pulse.material.opacity-=.08;if(pulse.material.opacity<=0){clearInterval(pulseTimer);scene.remove(pulse);pulse.geometry.dispose();pulse.material.dispose()}},35);for(const e of enemies){if(e.alive&&e.g.position.distanceTo(player.position)<7)damageEnemy(e,46,true)}showFeed('PULSO DO ECLIPSE · 35 ENERGIA');}else{if(playerState.attackCd>0)return;playerState.attackCd=.48;playerState.anim=.28;arms.forEach((a,i)=>a.rotation.x=-.9+(i*.25));setTimeout(()=>arms.forEach(a=>a.rotation.x=0),170);let hit=false;for(const e of enemies){if(!e.alive)continue;const dx=e.g.position.x-player.position.x,dz=e.g.position.z-player.position.z,dist=Math.hypot(dx,dz);const forward=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));const dot=(dx*forward.x+dz*forward.z)/(dist||1);if(dist<3.2&&dot>-.25){damageEnemy(e,30,false);hit=true}}if(!hit)showFeed('GOLPE NO AR');}}
