canvas.addEventListener('pointerdown',(e)=>{dragYaw=true;lastX=e.clientX;if(e.pointerType==='touch')return});
addEventListener('pointerup',()=>dragYaw=false);
canvas.addEventListener('pointermove',(e)=>{if(dragYaw&&started&&!paused){yaw-=e.clientX-lastX*.001;lastX=e.clientX}});

$('#start-btn').addEventListener('click',()=>{started=true;$('#intro').classList.add('hidden');message('Comece por entre as árvores');toast('Missão iniciada');updateStats()});
$('#resume-btn').addEventListener('click',togglePause);
$('#pause-btn').addEventListener('click',togglePause);
$('#ability-btn').addEventListener('click',()=>doAttack(true));
$('#touch-attack').addEventListener('pointerdown',(e)=>{e.preventDefault();doAttack(false)});
$('#touch-power').addEventListener('pointerdown',(e)=>{e.preventDefault();doAttack(true)});
$('#touch-jump').addEventListener('pointerdown',(e)=>{e.preventDefault();jump()});
$('#touch-dodge').addEventListener('pointerdown',(e)=>{e.preventDefault();dodge()});

const joystick=$('#joystick'),stick=joystick.querySelector('span');let joyPointer=null;
joystick.addEventListener('pointerdown',(e)=>{joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);updateJoystick(e)});
joystick.addEventListener('pointermove',(e)=>{if(e.pointerId===joyPointer)updateJoystick(e)});
for(const ev of ['pointerup','pointercancel','pointerleave'])joystick.addEventListener(ev,(e)=>{if(e.pointerId!==joyPointer)return;joyPointer=null;moveTouch.x=moveTouch.y=0;stick.style.transform='translate(-50%, -50%)'});
function updateJoystick(e){const r=joystick.getBoundingRect?joystick.getBoundingRect():joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,d=Math.hypot(dx,dy)||1;if(d>max){dx=dx/d*max;dy=dy/d*max}stick.style.transform=`translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;moveTouch.x=dx/max;moveTouch.y=dy/max}

function togglePause(){if(!started||gameWon)return;paused=!paused;$('#pause-screen').classList.toggle('hidden',!paused)}
function jump(){if(!started||paused||!playerState.onGround)return;playerState.vy=7.2;playerState.onGround=false}
function dodge(){if(!started||paused||playerState.dodge>0)return;playerState.dodge=.55;playerState.iframes=.55}
function blocked(x,z,r=.38){for(const o of obstacles){if(Math.hypot(x-o.x,z-o.z)<r+o.r)return true}return false}

addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-(lastTime||now))/1000,.033);lastTime=now;
  if(started&&!paused&&!gameWon){
    playerState.attackCd=Math.max(0,playerState.attackCd-dt);playerState.powerCd=Math.max(0,playerState.powerCd-dt);playerState.iframes=Math.max(0,playerState.iframes-dt);playerState.dodge=Math.max(0,playerState.dodge-dt);playerState.energy=Math.min(100,playerState.energy+dt*5);

    let mx=(keys.KeyD?1:0)-(keys.KeyA?1:0)+moveTouch.x,mz=(keys.KeyS?1:0)-(keys.KeyW?1:0)+moveTouch.y;
    const len=Math.hypot(mx,mz);if(len>.08){mx/=Math.max(1,len);mz/=Math.max(1,len);const speed=playerState.dodge>0?10:5.2;const sin=Math.sin(yaw),cos=Math.cos(yaw);const dx=(mx*cos-mz*sin)*speed*dt,dz=(mx*sin+mz*cos)*speed*dt;
      if(!blocked(player.position.x+dx,player.position.z,.42))player.position.x+=dx;if(!blocked(player.position.x,player.position.z+dz,.42))player.position.z+=dz;player.rotation.y=yaw+Math.atan2(mx,mz*-1)+Math.PI;playerState.anim+=dt*9;arms[0].rotation.z=Math.sin(playerState.anim)*.18;arms[1].rotation.z=-Math.sin(playerState.anim)*.18
    }else arms.forEach(a=>a.rotation.z*=.85);

    playerState.vy-=16*dt;player.position.y+=playerState.vy*dt;if(player.position.y<=0){player.position.y=0;playerState.vy=0;playerState.onGround=true}

    for(let i=shards.length-1;i>=0;i--){const s=shards[i];s.rotation.y+=dt*1.5;s.position.y=s.userData.baseY+Math.sin(now*.002+i)*.14;if(s.position.distanceTo(player.position)<1.45){const idx=s.userData.index;if(!(saved.shards||[]).includes(idx)){saved.shards=saved.shards||[];saved.shards.push(idx);save()}collected=saved.shards.length;s.visible=false;scene.remove(s);shards.splice(i,1);playerState.energy=Math.min(100,playerState.energy+25);playerState.xp+=100;showFeed('FRAGMENTO RECUPERADO · +100 XP');updateQuest();updateStats();if(collected>=3)startBoss()}}

    for(const e of enemies){if(!e.alive)continue;const g=e.g,dx=player.position.x-g.position.x,dz=player.position.z-g.position.z,dist=Math.hypot(dx,dz)||.1;e.attack-=dt;e.stun=Math.max(0,e.stun-dt);e.g.rotation.z*=.9;
      if(e.stun<=0&&dist> (e.boss?3.2:1.7)){const speed=(e.boss?2.1:e.type==='wisp'?2.8:e.type==='brute'?1.45:2.15)*dt;g.position.x+=(dx/dist)*speed;g.position.z+=(dz/dist)*speed}
      g.rotation.y=Math.atan2(dx,dz);if(dist<(e.boss?3.8:1.5)&&e.attack<=0){hitPlayer(e.boss?16:e.type==='brute'?11:7);e.attack=e.boss?1.05:e.type==='wisp'?1.6:1.9}
      if(e.boss){e.g.position.y=Math.sin(now*.002)*.08;e.bar.lookAt(camera.position);e.barBg.lookAt(camera.position)}else if(dist<5||e.hp<e.maxHp){e.bar.visible=e.barBg.visible=true;e.bar.lookAt(camera.position);e.barBg.lookAt(camera.position)}
    }
  }

  const target=new THREE.Vector3(player.position.x+Math.sin(yaw)*6*Math.cos(pitch),player.position.y+3.2+Math.sin(pitch)*6,player.position.z+Math.cos(yaw)*6*Math.cos(pitch));camera.position.lerp(target,.08);camera.lookAt(player.position.x,player.position.y+1.25,player.position.z);
  moteGeo.attributes.position.needsUpdate=true;ring.rotation.z+=.002;eclipse.rotation.y+=.001;beaconCore.rotation.y+=dt||.01;
  updateStats();renderer.render(scene,camera)}
requestAnimationFrame(animate);

